<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Policies\AuthPolicy;use App\Services\AssistedAdministrationService;use App\Services\TournamentOperationService;use App\Support\Database;use App\Support\Security;use App\Support\Session;use App\Support\View;
final class TournamentOperationController {
 private function db():\PDO{return Database::connection();} private function service():TournamentOperationService{return new TournamentOperationService($this->db());}
 private function tournament(int $id):array{$s=$this->db()->prepare('SELECT * FROM tournaments WHERE id=? AND deleted_at IS NULL');$s->execute([$id]);return$s->fetch()?:throw new \RuntimeException('Campeonato nao encontrado.');}
 private function matchAccess(int $tid,int $match,string $permission):array{$s=$this->db()->prepare('SELECT id FROM matches WHERE id=? AND tournament_id=? AND deleted_at IS NULL');$s->execute([$match,$tid]);if(!$s->fetchColumn()){http_response_code(404);exit('Partida nao encontrada.');}return AuthPolicy::requirePermission($permission,'matches',$match);}
 private function relation(int $tid,string $kind,int $id):void{$sql=['registration'=>'SELECT r.id FROM registrations r WHERE r.id=? AND r.tournament_id=? AND r.deleted_at IS NULL','group'=>'SELECT g.id FROM groups_competition g JOIN stages s ON s.id=g.stage_id WHERE g.id=? AND s.tournament_id=? AND g.deleted_at IS NULL','stage'=>'SELECT id FROM stages WHERE id=? AND tournament_id=? AND deleted_at IS NULL'];$s=$this->db()->prepare($sql[$kind]);$s->execute([$id,$tid]);if(!$s->fetchColumn()){http_response_code(404);exit('Recurso nao encontrado.');}}
 public function dashboard(array $p):string{$id=(int)$p['id'];$u=AuthPolicy::requireTournamentPermission('view',$id);$t=$this->tournament($id);$db=$this->db();$query=function(string $sql,array $args=[])use($db){$s=$db->prepare($sql);$s->execute($args);return$s->fetchAll();};$teams=$query('SELECT t.*,e.status entry_status,e.category_id FROM teams t JOIN team_tournament_entries e ON e.team_id=t.id WHERE e.tournament_id=? AND e.deleted_at IS NULL AND t.deleted_at IS NULL ORDER BY t.name',[$id]);$athletes=$query('SELECT p.*,tm.team_id,t.name team_name,pp.primary_position,pp.preferred_number FROM people p JOIN team_memberships tm ON tm.person_id=p.id JOIN teams t ON t.id=tm.team_id JOIN team_tournament_entries e ON e.team_id=tm.team_id LEFT JOIN person_profiles pp ON pp.person_id=p.id WHERE e.tournament_id=? AND p.person_type="athlete" AND p.deleted_at IS NULL AND tm.deleted_at IS NULL GROUP BY p.id ORDER BY t.name,p.full_name',[$id]);$staff=$query('SELECT p.full_name,tm.role,t.name team_name,tm.status FROM people p JOIN team_memberships tm ON tm.person_id=p.id JOIN teams t ON t.id=tm.team_id JOIN team_tournament_entries e ON e.team_id=tm.team_id WHERE e.tournament_id=? AND p.person_type="staff" AND p.deleted_at IS NULL AND tm.deleted_at IS NULL ORDER BY t.name,p.full_name',[$id]);$stages=$query('SELECT * FROM stages WHERE tournament_id=? AND deleted_at IS NULL ORDER BY stage_order',[$id]);$groups=$query('SELECT g.*,s.name stage_name,(SELECT COUNT(*) FROM group_team_assignments a WHERE a.group_id=g.id AND a.deleted_at IS NULL) members FROM groups_competition g JOIN stages s ON s.id=g.stage_id WHERE s.tournament_id=? AND g.deleted_at IS NULL ORDER BY g.group_order',[$id]);foreach($groups as &$group){$group['teams']=$query('SELECT t.id,t.name FROM group_team_assignments a JOIN teams t ON t.id=a.team_id WHERE a.group_id=? AND a.deleted_at IS NULL ORDER BY a.display_order',[(int)$group['id']]);}unset($group);$registrations=$query('SELECT r.*,p.full_name,t.name team_name FROM registrations r JOIN people p ON p.id=r.person_id JOIN teams t ON t.id=r.team_id WHERE r.tournament_id=? AND r.deleted_at IS NULL ORDER BY r.id DESC',[$id]);$matches=$query('SELECT m.*,h.name home_name,a.name away_name,s.name stage_name,r.name round_name FROM matches m JOIN teams h ON h.id=m.home_team_id JOIN teams a ON a.id=m.away_team_id LEFT JOIN stages s ON s.id=m.stage_id LEFT JOIN rounds r ON r.id=m.round_id WHERE m.tournament_id=? AND m.deleted_at IS NULL ORDER BY m.scheduled_at,m.id',[$id]);$candidates=[];foreach($matches as $m){foreach([(int)$m['home_team_id'],(int)$m['away_team_id']] as $teamId){$candidates[$m['id']][$teamId]=$query('SELECT p.id,p.full_name,r.shirt_number FROM registrations r JOIN people p ON p.id=r.person_id WHERE r.tournament_id=? AND r.team_id=? AND r.status="approved" AND r.deleted_at IS NULL ORDER BY p.full_name',[$id,$teamId]);}}$categories=$query('SELECT id,name FROM categories WHERE status="active" AND deleted_at IS NULL ORDER BY display_order,name');$counts=['pending'=>count(array_filter($registrations,fn($r)=>in_array($r['status'],['draft','submitted','under_review','pending'],true))),'suspensions'=>(int)$db->query('SELECT COUNT(*) FROM suspensions WHERE tournament_id='.(int)$id.' AND status="active" AND deleted_at IS NULL')->fetchColumn(),'future'=>count(array_filter($matches,fn($m)=>in_array($m['status'],['scheduled','confirmed'],true)))];return View::render('admin/tournament-operations',['title'=>'Operação do campeonato','user'=>$u,'tournament'=>$t,'teams'=>$teams,'athletes'=>$athletes,'staff'=>$staff,'stages'=>$stages,'groups'=>$groups,'registrations'=>$registrations,'matches'=>$matches,'candidates'=>$candidates,'categories'=>$categories,'counts'=>$counts]);}
 public function createTeam(array $p):never{$tid=(int)$p['id'];AuthPolicy::requireTournamentPermission('manage_roster',$tid);Security::verifyCsrf($_POST['_csrf']??null);try{(new AssistedAdministrationService($this->db()))->createTeam($tid,$_POST);Session::flash('success','Equipe cadastrada e vinculada ao campeonato.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation#equipes');}
 public function teamStatus(array $p):never{$tid=(int)$p['id'];AuthPolicy::requireTournamentPermission('manage_roster',$tid);Security::verifyCsrf($_POST['_csrf']??null);try{(new AssistedAdministrationService($this->db()))->setTeamStatus($tid,(int)($_POST['team_id']??0),(string)($_POST['action']??''));Session::flash('success','Situação da equipe atualizada.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation#equipes');}
 public function createAthlete(array $p):never{$tid=(int)$p['id'];AuthPolicy::requireTournamentPermission('manage_roster',$tid);Security::verifyCsrf($_POST['_csrf']??null);try{(new AssistedAdministrationService($this->db()))->createAthlete($tid,$_POST);Session::flash('success','Atleta cadastrado e vinculado à equipe.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation#atletas');}
 public function createStaff(array $p):never{$tid=(int)$p['id'];AuthPolicy::requireTournamentPermission('manage_roster',$tid);Security::verifyCsrf($_POST['_csrf']??null);try{(new AssistedAdministrationService($this->db()))->createStaff($tid,$_POST);Session::flash('success','Membro da comissão cadastrado.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation#comissao');}
 public function register(array $p):never{$tid=(int)$p['id'];$u=AuthPolicy::requireTournamentPermission('manage_roster',$tid);Security::verifyCsrf($_POST['_csrf']??null);try{$this->service()->registerAthlete($tid,(int)$_POST['team_id'],(int)$_POST['person_id'],$_POST['shirt_number']??null);Session::flash('success','Inscricao criada.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function review(array $p):never{$tid=(int)$p['id'];$status=(string)($_POST['status']??'');$u=AuthPolicy::requireTournamentPermission($status==='approved'?'approve_registration':'reject_registration',$tid);Security::verifyCsrf($_POST['_csrf']??null);$this->relation($tid,'registration',(int)$_POST['registration_id']);try{$this->service()->setRegistrationStatus((int)$_POST['registration_id'],$status,(int)$u['id'],$_POST['reason']??null);Session::flash('success','Inscricao atualizada.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function group(array $p):never{$tid=(int)$p['id'];AuthPolicy::requireTournamentPermission('manage_bracket',$tid);Security::verifyCsrf($_POST['_csrf']??null);$this->relation($tid,'stage',(int)$_POST['stage_id']);try{$this->service()->createGroup((int)$_POST['stage_id'],trim((string)$_POST['name']),trim((string)$_POST['code']),(int)$_POST['max_teams']);Session::flash('success','Grupo criado.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function assign(array $p):never{$tid=(int)$p['id'];AuthPolicy::requireTournamentPermission('manage_bracket',$tid);Security::verifyCsrf($_POST['_csrf']??null);$this->relation($tid,'group',(int)$_POST['group_id']);try{$this->service()->assignTeam((int)$_POST['group_id'],(int)$_POST['team_id']);Session::flash('success','Equipe distribuida.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function removeAssignment(array $p):never{$tid=(int)$p['id'];AuthPolicy::requireTournamentPermission('manage_bracket',$tid);Security::verifyCsrf($_POST['_csrf']??null);$this->relation($tid,'group',(int)$_POST['group_id']);try{$this->service()->removeTeamFromGroup((int)$_POST['group_id'],(int)$_POST['team_id']);Session::flash('success','Equipe retirada do grupo.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation#grupos');}
 public function schedule(array $p):never{$tid=(int)$p['id'];AuthPolicy::requireTournamentPermission('manage_bracket',$tid);Security::verifyCsrf($_POST['_csrf']??null);$this->relation($tid,'group',(int)$_POST['group_id']);try{$n=count($this->service()->generateGroupMatches((int)$_POST['group_id'],$_POST['start_at']?:null));Session::flash('success',$n.' partidas geradas.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function lineup(array $p):never{$tid=(int)$p['id'];$this->matchAccess($tid,(int)$_POST['match_id'],'manage_lineup');Security::verifyCsrf($_POST['_csrf']??null);try{$players=[];foreach($_POST['players']??[] as $person=>$row)if(!empty($row['selected']))$players[]=['person_id'=>(int)$person,'role'=>($row['role']??'substitute'),'shirt_number'=>$row['number']??'','captain'=>!empty($row['captain']),'goalkeeper'=>!empty($row['goalkeeper'])];$this->service()->saveLineup((int)$_POST['match_id'],(int)$_POST['team_id'],$players);Session::flash('success','Escalacao salva.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function event(array $p):never{$tid=(int)$p['id'];$u=$this->matchAccess($tid,(int)$_POST['match_id'],'operate_match');Security::verifyCsrf($_POST['_csrf']??null);try{$this->service()->event((int)$_POST['match_id'],['team_id'=>(int)$_POST['team_id'],'person_id'=>(int)($_POST['person_id']??0)?:null,'assist_person_id'=>(int)($_POST['assist_person_id']??0)?:null,'event_type'=>(string)$_POST['event_type'],'minute'=>(int)($_POST['minute']??0)?:null,'period'=>$_POST['period']??'first'],(int)$u['id']);Session::flash('success','Evento registrado.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function finish(array $p):never{$tid=(int)$p['id'];$this->matchAccess($tid,(int)$_POST['match_id'],'finish_match');Security::verifyCsrf($_POST['_csrf']??null);try{$this->service()->finish((int)$_POST['match_id']);Session::flash('success','Partida pronta para homologacao.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function homologate(array $p):never{$tid=(int)$p['id'];$u=$this->matchAccess($tid,(int)$_POST['match_id'],'homologate_match');Security::verifyCsrf($_POST['_csrf']??null);try{$this->service()->homologate((int)$_POST['match_id'],(int)$u['id']);Session::flash('success','Resultado homologado.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function rectify(array $p):never{$tid=(int)$p['id'];$u=$this->matchAccess($tid,(int)$_POST['match_id'],'approve_rectification');Security::verifyCsrf($_POST['_csrf']??null);try{$this->service()->rectify((int)$_POST['match_id'],trim((string)$_POST['reason']),(int)$u['id']);Session::flash('success','Retificacao iniciada.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function knockout(array $p):never{$tid=(int)$p['id'];AuthPolicy::requireTournamentPermission('manage_bracket',$tid);Security::verifyCsrf($_POST['_csrf']??null);try{$n=count($this->service()->generateKnockout($tid));Session::flash('success',$n.' partidas eliminatorias geradas.');}catch(\Throwable $e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/tournaments/'.$tid.'/operation');}
 public function pdf(array $p):never{$tid=(int)$p['id'];$this->matchAccess($tid,(int)$p['match'],'download_private_file');$s=$this->db()->prepare('SELECT report_pdf_path FROM matches WHERE id=? AND tournament_id=?');$s->execute([(int)$p['match'],$tid]);$path=$s->fetchColumn();$file=$path?dirname(__DIR__,2).'/storage/'.$path:null;if(!$file||!is_file($file)){http_response_code(404);exit('Sumula indisponivel.');}header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="sumula-'.$p['match'].'.pdf"');readfile($file);exit;}
 public function report(array $p):string{$tid=(int)$p['id'];$match=(int)$p['match'];$u=$this->matchAccess($tid,$match,'view');$db=$this->db();$s=$db->prepare('SELECT m.*,t.name tournament_name,h.name home_name,a.name away_name,st.name stage_name,g.name group_name,r.name round_name FROM matches m JOIN tournaments t ON t.id=m.tournament_id JOIN teams h ON h.id=m.home_team_id JOIN teams a ON a.id=m.away_team_id LEFT JOIN stages st ON st.id=m.stage_id LEFT JOIN groups_competition g ON g.id=m.group_id LEFT JOIN rounds r ON r.id=m.round_id WHERE m.id=? AND m.tournament_id=?');$s->execute([$match,$tid]);$row=$s->fetch();if(!$row){http_response_code(404);return View::render('errors/404',['title'=>'Súmula não encontrada']);}$events=$db->prepare('SELECT e.*,p.full_name,t.name team_name FROM match_events e LEFT JOIN people p ON p.id=e.person_id LEFT JOIN teams t ON t.id=e.team_id WHERE e.match_id=? AND e.deleted_at IS NULL ORDER BY e.id');$events->execute([$match]);$lineups=$db->prepare('SELECT l.*,p.full_name,t.name team_name FROM match_lineups l JOIN people p ON p.id=l.person_id JOIN teams t ON t.id=l.team_id WHERE l.match_id=? AND l.deleted_at IS NULL ORDER BY t.name,l.lineup_role,p.full_name');$lineups->execute([$match]);return View::render('admin/match-report',['title'=>'Súmula digital','user'=>$u,'match'=>$row,'events'=>$events->fetchAll(),'lineups'=>$lineups->fetchAll()]);}
}
